#!/usr/bin/env node
import { readdir, readFile, mkdir, writeFile } from 'node:fs/promises'; import { dirname, join, relative, resolve } from 'node:path'; import { pathToFileURL } from 'node:url'; import { digestBytes } from '../lib/artifacts/digests.mjs'; import { transformSkillText } from '../lib/skills/transform.mjs'; import { skillUri } from '../lib/skills/uri.mjs';
async function walk(root) { const entries = await readdir(root, { withFileTypes: true }); const nested = await Promise.all(entries.map(async (entry) => entry.isDirectory() ? walk(join(root, entry.name)) : [join(root, entry.name)])); return nested.flat().sort(); }
export async function importSkillBundle({ source, bundle, output, manifestPath, receiptPath, version, provenance, licenseState, rightsReceipt=null, rules = [] }) { if(!licenseState)throw new TypeError('licenseState is required');if(licenseState==='unresolved'&&rightsReceipt!==null)throw new TypeError('unresolved rights cannot have a receipt');if(licenseState!=='unresolved'&&!rightsReceipt)throw new TypeError('resolved rights require an explicit receipt');const sourceRoot = resolve(source); const outputRoot = resolve(output); const records = []; for (const file of await walk(sourceRoot)) { const path = relative(sourceRoot, file).replaceAll('\\', '/'); const sourceBytes = await readFile(file); const transformed = transformSkillText(sourceBytes.toString('utf8'), { bundle, path, profile: 'audit', rules }); await mkdir(dirname(join(outputRoot, path)), { recursive: true }); await writeFile(join(outputRoot, path), transformed); records.push({ path, uri: skillUri(bundle, path), sourceDigest: digestBytes(sourceBytes), outputDigest: digestBytes(Buffer.from(transformed)), transformations: rules.map(({ id }) => id).filter(Boolean) }); } const manifest = { schemaVersion: 1, id: bundle, version, entry: 'SKILL.md', rootUri: `legion-skill://${bundle}/`, provenance, licenseState, rightsReceipt, profiles: { audit: { mutation: false, publish: false }, authoring: { mutation: true, publish: false, externalOnly:true } }, files: records }; await mkdir(dirname(resolve(manifestPath)), { recursive: true }); await writeFile(resolve(manifestPath), `${JSON.stringify(manifest, null, 2)}\n`); const receipt={ schemaVersion: 1, kind: 'legion-skill-import-receipt', bundle, version, sourceFileCount: records.length, sourceDigest: digestBytes(Buffer.from(records.map(({ sourceDigest }) => sourceDigest).join('\n'))), outputDigest: digestBytes(Buffer.from(records.map(({ outputDigest }) => outputDigest).join('\n'))), manifestPath: resolve(manifestPath), provenance,licenseState,rightsReceipt };const receiptFile=resolve(receiptPath??`${manifestPath}.import-receipt.json`);await mkdir(dirname(receiptFile),{recursive:true});await writeFile(receiptFile,`${JSON.stringify(receipt,null,2)}\n`);return{...receipt,receiptPath:receiptFile}; }
function arg(name) { const index = process.argv.indexOf(`--${name}`); return index < 0 ? null : process.argv[index + 1]; }
async function main() { const source = arg('source'); const bundle = arg('bundle'); const output = arg('output'); const manifestPath = arg('manifest'); const receiptPath=arg('receipt');const version = arg('version'); const provenance = arg('provenance');const licenseState=arg('license-state');const rightsReceipt=arg('rights-receipt'); if (![source,bundle,output,manifestPath,receiptPath,version,provenance,licenseState].every(Boolean)) throw new Error('usage: import-skill-bundle --source DIR --bundle ID --output DIR --manifest FILE --receipt FILE --version VERSION --provenance SOURCE --license-state STATE [--rights-receipt ID]'); const receipt = await importSkillBundle({ source, bundle, output, manifestPath,receiptPath, version, provenance,licenseState,rightsReceipt, rules: [{ id: 'approving-human', from: 'the operator', to: 'the approving human' }] }); process.stdout.write(`${JSON.stringify(receipt)}\n`); }
if (import.meta.url === pathToFileURL(process.argv[1]).href) main().catch((error) => { console.error(error.message); process.exitCode = 1; });
